const NS_PAPEIS_SEQ = ["normalidade", "estimulo", "reacao", "consequencia"];
let NS_N = 0;
for (const def of [...NR.values()].filter(d => !d.sub)) { const temas = NS_TEMAS[def.familia] || []; if (!temas.length) continue;
  const irmas = [...NR.values()].filter(d => !d.sub && d.familia === def.familia), i = irmas.indexOf(def);
  for (let j = 0; j < 3; j++) { const [slug, nome, e, r, c] = temas[(i * 3 + j) % temas.length], E = NS_ESTIMULO[e], RR = NS_REACAO[r], C = NS_CONSEQ[c]; if (!E || !RR || !C) continue;
    const normal = def.beats[0].replace(/\sk(\s|$)/, " ").replace(/\s+/g, " ").trim(), papeis = Math.max(def.papeis, /\bB:/.test(E[0] + RR[0] + C[0]) ? 2 : 1), id = def.id + "." + slug;
    NR.set(id, { id, nome: def.nome + " — " + nome, fonte: "subfunção: " + E[1] + " → " + RR[1] + " → " + C[1], papeis, intensidade: def.intensidade, beats: [normal, E[0], RR[0], C[0]], familia: def.familia, funcao: def.id, sub: true, sequencia: NS_PAPEIS_SEQ.slice() }); NS_N++; } }
function nrListarSub(funcao) { return [...NR.values()].filter(d => d.sub && (!funcao || d.funcao === funcao)).map(d => ({ id: d.id, nome: d.nome, funcao: d.funcao, familia: d.familia, familiaNome: NR_FAMILIAS[d.familia], encenacao: d.fonte.replace(/^subfunção: /, ""), papeis: d.papeis, sequencia: d.sequencia })); }
function nrArvore() { const out = {}; for (const d of NR.values()) { if (d.sub) continue; const f = out[d.familia] || (out[d.familia] = { nome: NR_FAMILIAS[d.familia], funcoes: {} }); f.funcoes[d.id] = { nome: d.nome, sub: nrListarSub(d.id).map(s => ({ id: s.id, nome: s.nome.split(" — ")[1], encenacao: s.encenacao })) }; } return out; }
const NR_SUB_TOTAL = NS_N;
export { NS_ESTIMULO, NS_REACAO, NS_CONSEQ, NS_TEMAS, nrListarSub, nrArvore, NR_SUB_TOTAL };
